"""62편 그림 프롬프트 → 62_prompts.txt (python 62_prompts.py). 스타일 끝말은 2TAN-MASTER §5에서 그대로 읽음(11/6 인기 5편 기준판)."""
S = next(l.strip() for l in open("2TAN-MASTER.md", encoding="utf-8") if l.startswith("Style: a hyper-detailed"))
E = "Keep exactly the same place, objects, red props and light."
HI = "A high oblique aerial view from about 150 m up, looking 35 degrees down"
BR = ("Banpo Bridge in Seoul: a long double-deck concrete girder bridge across the very wide Han River, the upper road deck carried on wide piers "
      "and the low Jamsu Bridge deck running just above the water directly underneath; along both outer edges of the upper deck runs a long row of small "
      "nozzles that shoot many thin arcs of water outward, falling about 20 m in a long glittering curtain into the river on both sides of the bridge")
SUN = "Golden hour just after sunset: the sky is light peach and soft blue, warm light on the water, and the falling water glows softly in gentle rainbow colours from underwater lights; bright and inviting, not a night scene."
P = [
 ("01", None, f"{HI} along the very wide Han River that runs straight toward the horizon; the sky and horizon fill the top fifth. In the lower half is {BR}. Apartment towers and riverside parks line both banks into the distance. {SUN} No red props."),
 ("01b", None, f"Seen from a low height just above the river surface, close to the side of {BR}; the long glittering water curtain falls in front of the viewer from the upper deck edge into the river, the low Jamsu Bridge deck just above the water behind it, and on the riverside park to the right a big crowd of tiny white figurines sits on the grass steps watching. {SUN} No red props."),
 ("02", None, f"Seen from the riverside park beside {BR}: in the foreground wide grass steps and a promenade packed with a big crowd of tiny white figurines sitting and standing, all facing the bridge; the long glowing water curtain spans the frame behind them. {SUN} No red props."),
 ("03", None, "Seen from the riverside park: the same long double-deck concrete bridge across the very wide Han River on an overcast grey afternoon after rain; the river water is muddy light brown and choppy, the row of nozzles along the bridge edge is completely still and no water is shooting; a few tiny white figurines stand at the railing looking at the bridge. A small thin red 3D question mark floats beside the bridge edge, much smaller than the bridge pier."),
 ("04", "01b", "Change the camera and the ground: the view has sunk to the water line, so the lower half of the frame is now a clean cut-away section under the river surface: green-blue river water, the sandy brown riverbed and the concrete bridge pier foundation; on the riverbed beside the pier stand several grey cylindrical submersible pumps, each with a thick grey pipe that climbs up the side of the pier to the nozzles on the upper deck edge, where the water curtain shoots out. No red props."),
 ("05", None, f"{HI} at the side of the same long double-deck concrete bridge across the very wide Han River on a clear sunny day in 2007: no fountain yet; small yellow work barges with cranes float beside the piers, tiny white figurine workers in plain white helmets on a hanging work platform under the upper deck edge install a long grey pipe; orange safety fences on the riverside park. Calm and orderly. No red props."),
 ("06", None, "A large 3D map of central Seoul in miniature seen from high above at an angle: the very wide Han River curves across the middle with its riverside parks, roads and apartment blocks on both banks and green mountains at the edges; one long double-deck bridge crosses the river in the centre; a thin bright red 3D dimension line with end ticks runs across the river from bank to bank beside the bridge, and a second thin red dimension line runs along the length of the bridge. Bright daylight, warm sunlight."),
 ("07", "04", "Change only the camera and the light: it is now a clear sunny day, the fountain is off, and the view is a wide cut-away along the riverbed under the bridge, showing a long row of many identical grey cylindrical submersible pumps standing on the riverbed along the pier foundations into the distance, each with its pipe climbing up the pier. One thin red 3D dimension line runs along the row of pumps, smaller than the pumps."),
 ("07e", "07", "Change only the camera: it is now close to one submersible pump with its thick pipe and cable, which fill the middle third of the frame; the next pumps are softly visible behind it."),
 ("08", None, f"Seen from just beside the outer edge of the upper deck of {BR}, looking along the bridge edge into the distance: a long straight row of many small identical nozzles runs from the near foreground to the horizon, each shooting a thin arc of water outward that falls toward the river far below. {SUN} No red props."),
 ("08o", "08", "Change only the camera: it has moved 30 degrees to the right around the row of nozzles, now looking back along the bridge edge slightly from the river side, so more of the falling water curtain and the river below are visible."),
 ("09", None, f"Side view from over the river, level with the bridge: {BR}; the full height of one falling arc of water is visible from the nozzle at the upper deck edge down to the splash on the river surface, with the low Jamsu Bridge deck just above the water. {SUN} No red props."),
 ("10", None, f"Seen from very high above at an angle: the whole length of {BR}, with the water curtain falling on both sides along the entire bridge from bank to bank; the very wide Han River, both riverbanks with parks, roads and apartment blocks, and the city stretching to the mountains; the sky fills the top fifth. {SUN} No red props."),
 ("11", None, "Seen from above at an angle: the riverside park at the foot of a long double-deck concrete bridge on a sunny spring day in 2009; a small outdoor stage area in front of the bridge where a group of tiny white figurines stand in a row holding plain blank white placards, a few figurines with small blank cameras face them, the bridge and its row of nozzles (off) behind them, newly laid concrete plaza around. No red props."),
 ("12", None, "Inside a clean, brightly lit electrical room in miniature, seen from above at a 45-degree angle: two long rows of tall grey switchboard cabinets with closed blank doors, thick black cables in cable trays overhead running out through the wall toward the bridge, one tiny white figurine worker in the aisle. No red props."),
 ("13", None, "Seen from the riverside park: the same long double-deck concrete bridge across the very wide Han River on a very windy grey day; the fountain is off and no water is shooting; the river surface is rough with white-capped waves, the riverside trees bend in the wind and flags on poles stand straight out. A thin bright red 3D arrow beside the bridge shows the wind direction, much smaller than the bridge pier. No other red props."),
 ("14", None, "Seen from the riverside park: the same long double-deck concrete bridge across the very wide Han River under heavy dark-grey rain clouds that are rolling in; the first raindrops speckle the river, the fountain is off and no water is shooting, tiny white figurines with plain umbrellas walk away along the promenade. No red props."),
 ("16", None, "Inside a clean, brightly lit fountain control room in miniature seen from above at a 45-degree angle: a wide window looks out onto the long bridge with its water curtain falling; in front of the window a long control desk with blank dark screens and rows of plain buttons and sliders, two tiny white figurine operators seated. A small thin red 3D clock-face ring without numbers floats above the desk, much smaller than the desk."),
 ("17", None, f"Seen from very high above the very wide Han River at an angle: the whole city of Seoul with apartment towers, riverside parks and mountains, the sky filling the top fifth; in the middle {BR}; under the bridge the river is cut away in a clean section showing the long row of grey submersible pumps on the riverbed with their pipes climbing the piers to the water curtain. {SUN} No red props."),
]
with open("62_prompts.txt", "w", encoding="utf-8") as f:
    for n, src, t in P:
        if src: f.write(f"[{n}.jpg] ({src}.jpg를 열어 편집)\n{E} {t} No letters or numbers anywhere.\n\n")
        else: f.write(f"[{n}.jpg]\n{t} {S}\n\n")
print(len(P))
